function readHubSpotPage(body) {
  if (!Array.isArray(body?.results)) throw new Error("Invalid HubSpot contacts page");
  const next = body.paging?.next;
  if (next != null && (typeof next.after !== "string" || !next.after.trim())) {
    throw new Error("Invalid HubSpot contact cursor");
  }
  return { rows: body.results, cursor: next?.after ?? null };
}

export default function step({ state, body }) {
  const page = body === null ? null : readHubSpotPage(body);
  const before = state ?? { rows: [], seen: [] };
  const current = page ? addPage(before, page.rows, page.cursor, "hubspot") : before;
  return {
    state: current,
    more: page === null || page.cursor !== null,
    query: {
      limit: "100",
      properties: "email,firstname,hs_additional_emails",
      ...(page?.cursor ? { after: page.cursor } : {}),
    },
  };
}

