function indexEmails(rows) {
  const identities = new Map();
  for (const row of rows) {
    for (const alias of row.aliases) {
      if (!identities.has(alias)) identities.set(alias, new Set());
      identities.get(alias).add(row.id);
    }
  }
  return identities;
}

function planCopies(pipedrive, hubspot) {
  const copies = [];
  const ambiguous = new Set();
  let missingPipedriveName = 0;
  const p = indexEmails(pipedrive);
  const h = indexEmails(hubspot);
  for (const [rows, source, target, destination] of [
    [pipedrive, p, "hubspot", h],
    [hubspot, h, "pipedrive", p],
  ]) {
    const selected = new Set();
    for (const { email, firstName, aliases } of rows) {
      if (!email || selected.has(email) || aliases.some((alias) => destination.has(alias)))
        continue;
      selected.add(email);
      if (source.get(email)?.size !== 1) {
        ambiguous.add(target + "/" + email);
        continue;
      }
      if (target === "pipedrive" && !firstName) {
        missingPipedriveName++;
        continue;
      }
      copies.push({ target, email, firstName });
    }
  }
  return {
    copies,
    totals: {
      hubspotCreated: copies.filter((item) => item.target === "hubspot").length,
      pipedriveCreated: copies.filter((item) => item.target === "pipedrive").length,
      ambiguousEmails: ambiguous.size,
      missingPipedriveName,
    },
  };
}

export default ({ pipedrive, hubspot }) => planCopies(pipedrive.rows, hubspot.rows);

