function requestBody(item) {
  if (item.target === "pipedrive") {
    return { name: item.firstName, emails: [{ value: item.email, primary: true }] };
  }
  return {
    properties: { email: item.email, ...(item.firstName ? { firstname: item.firstName } : {}) },
  };
}

export default ({ contact }) => requestBody(contact);

