function emailKey(value) {
  if (typeof value !== "string") return null;
  const email = value.trim().toLowerCase();
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) ? email : null;
}

function confirmContact(body, item) {
  const id = body?.id;
  const actualEmail =
    item.target === "pipedrive"
      ? body?.emails?.find((email) => emailKey(email?.value) === item.email)?.value
      : body?.properties?.email;
  if (
    (typeof id !== "string" && typeof id !== "number") ||
    !String(id).trim() ||
    emailKey(actualEmail) !== item.email
  ) {
    throw new Error(
      item.target +
        " contact creation was not confirmed. Check the destination CRM before rerunning.",
    );
  }
}

export default ({ receipt, contact }) => {
  confirmContact(receipt, contact);
  return {};
};

